import { randomUUID } from "node:crypto";

import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

type DocumentOut = { id: string; vendor_id: string; kind: string; status: string; created_at: string };
type ExtractionOut = { id: string; document_id: string; kind: string; status: string };
type VendorOut = { id: string; status: string; submitted_at: string | null };
type ReviewQueueItem = { vendor_id: string; extractions: ExtractionOut[] };
type AuditTrail = { items: { action: string }[] };

async function uploadDocument(api: APIRequestContext, vendorId: string, kind: "w9" | "insurance_certificate" | "contract") {
  const response = await api.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: {
        name: `${kind}-${randomUUID()}.pdf`,
        mimeType: "application/pdf",
        buffer: Buffer.from("%PDF-1.4 lifecycle test"),
      },
    },
  });
  return expectStatus<DocumentOut>(response, 201);
}

async function extractionFor(api: APIRequestContext, documentId: string) {
  return expectStatus<ExtractionOut>(await api.get(`/api/documents/${documentId}/extraction`), 200);
}

test.describe("vendor lifecycle", () => {
  test(
    "approving the replacement approves a vendor whose other documents were already approved",
    { tag: "@LIF-06" },
    async ({ apiAs }) => {
      // Arrange: a vendor with insurance and contract approved, and a replacement w9 pending.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const uid = randomUUID().slice(0, 8);

      const vendor = await expectStatus<VendorOut>(
        await member.post("/api/vendors", {
          data: {
            name: `LIF06 Lifecycle ${uid}`,
            category: "services",
            contact_email: `ap-${uid}@lifecycle.test`,
          },
        }),
        201,
      );

      const insurance = await uploadDocument(member, vendor.id, "insurance_certificate");
      const contract = await uploadDocument(member, vendor.id, "contract");
      const originalW9 = await uploadDocument(member, vendor.id, "w9");

      const submitted = await expectStatus<VendorOut>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
      expect(submitted.status).toBe("in_review");

      const insuranceExtraction = await extractionFor(reviewer, insurance.id);
      const contractExtraction = await extractionFor(reviewer, contract.id);
      const originalExtraction = await extractionFor(reviewer, originalW9.id);

      await expectStatus<ExtractionOut>(
        await reviewer.post(`/api/extractions/${insuranceExtraction.id}/decision`, {
          data: { decision: "approve" },
        }),
        200,
      );
      await expectStatus<ExtractionOut>(
        await reviewer.post(`/api/extractions/${contractExtraction.id}/decision`, {
          data: { decision: "approve" },
        }),
        200,
      );
      const sentBack = await expectStatus<ExtractionOut>(
        await reviewer.post(`/api/extractions/${originalExtraction.id}/decision`, {
          data: { decision: "reject", note: "Illegible taxpayer ID" },
        }),
        200,
      );
      expect(sentBack.status).toBe("rejected");

      const replacementW9 = await uploadDocument(member, vendor.id, "w9");
      expect(replacementW9.id).not.toBe(originalW9.id);

      const resubmitted = await expectStatus<VendorOut>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
      expect(resubmitted.status).toBe("in_review");

      const replacementExtraction = await extractionFor(reviewer, replacementW9.id);
      expect(replacementExtraction.status).toBe("pending_review");

      // The replacement must be the only pending extraction for this vendor.
      const queue = await expectStatus<ReviewQueueItem[]>(await reviewer.get("/api/review-queue"), 200);
      const item = queue.find((entry) => entry.vendor_id === vendor.id);
      expect(item).toBeDefined();
      const pendingIds = (item?.extractions ?? [])
        .filter((e) => e.status === "pending_review")
        .map((e) => e.id);
      expect(pendingIds).toEqual([replacementExtraction.id]);

      // Act: approve the replacement w9.
      const decided = await expectStatus<ExtractionOut>(
        await reviewer.post(`/api/extractions/${replacementExtraction.id}/decision`, {
          data: { decision: "approve" },
        }),
        200,
      );
      expect(decided.status).toBe("approved");

      // Assert: vendor is approved and the audit trail records it.
      const approvedVendor = await expectStatus<VendorOut>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
      expect(approvedVendor.status).toBe("approved");

      const audit = await expectStatus<AuditTrail>(await reviewer.get(`/api/vendors/${vendor.id}/audit`), 200);
      expect(audit.items.map((event) => event.action)).toContain("vendor.approved");
    },
  );
});
